interface LanguageContextValue {
  language: Language
  translate: (text: string) => string
  selectLanguage: (language: Language) => void
}

const LanguageContext = createContext<LanguageContextValue | null>(null)
const storageKey = 'duopole-language'

function getInitialLanguage(): Language {
  const savedLanguage = localStorage.getItem(storageKey)
  return languages.find(({ code }) => code === savedLanguage)?.code ?? 'en'
}

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language] = useState<Language>(getInitialLanguage)

  useEffect(() => {
    document.documentElement.lang = language
  }, [language])

  const value = useMemo<LanguageContextValue>(() => ({
    language,
    translate: (text) => language === 'en' ? text : translations[language][text] ?? text,
    selectLanguage: (nextLanguage) => {
      if (nextLanguage === language) return
      localStorage.setItem(storageKey, nextLanguage)
      window.location.reload()
    },
  }), [language])

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>
}

export function useLanguage() {
  const context = useContext(LanguageContext)
  if (!context) throw new Error('useLanguage must be used within a LanguageProvider')
  return context
}
